function build(api) {
  api.name('Ornamental Fish Topiary');
  const C_LEAF = 0x228B22, C_LEAF_L = 0x32CD32, C_GOLD = 0xDAA520, C_WHITE = 0xF5F5F5, C_BLACK = 0x000000, C_POT = 0xB6634F, C_SOIL = 0x3E2723;

  api.group('planter', 'planter');
    api.cyl({rTop: 1.3, rBot: 1.0, h: 1.5, pos: [0, 0.75, 0], color: C_POT});
    api.torus({r: 1.3, tube: 0.1, pos: [0, 1.5, 0], color: C_GOLD});
    api.cyl({r: 1.2, h: 0.2, pos: [0, 1.4, 0], color: C_SOIL});
  api.endGroup();

  api.group('tail', 'tail');
    api.box({w: 1.0, h: 1.5, d: 1.0, pos: [0, 2.25, 0], color: C_LEAF});
    api.tri({a: [0, 1.5, 0], b: [-1.8, 3.0, 0], c: [0, 3.0, 0], d: 0.3, color: C_LEAF});
    api.tri({a: [0, 1.5, 0], b: [1.8, 3.0, 0], c: [0, 3.0, 0], d: 0.3, color: C_LEAF});
    api.poly({r: 0.1, pos: [-1.8, 3.0, 0], color: C_GOLD});
    api.poly({r: 0.1, pos: [1.8, 3.0, 0], color: C_GOLD});
    api.poly({r: 0.1, pos: [-1.0, 2.8, 0], color: C_GOLD});
    api.poly({r: 0.1, pos: [1.0, 2.8, 0], color: C_GOLD});
  api.endGroup();

  api.group('body', 'body');
    api.box({w: 3.5, h: 3.0, d: 2.5, pos: [0, 4.5, 0], color: C_LEAF});
    api.box({w: 2.5, h: 1.5, d: 2.0, pos: [0, 6.5, 0], color: C_LEAF});
    api.torus({r: 1.8, tube: 0.1, pos: [0, 4.5, 0], color: C_GOLD});
    api.chain({waypoints: [[1.8, 3.5, 0.5], [1.8, 4.5, 0.5], [1.3, 6.0, 0.5]], r: 0.08, color: C_GOLD});
    api.chain({waypoints: [[-1.8, 3.5, 0.5], [-1.8, 4.5, 0.5], [-1.3, 6.0, 0.5]], r: 0.08, color: C_GOLD});
    api.poly({r: 0.15, pos: [1.5, 4.0, 1.3], color: C_GOLD});
    api.poly({r: 0.15, pos: [-1.0, 5.0, 1.3], color: C_GOLD});
    api.poly({r: 0.15, pos: [0.5, 3.5, 1.3], color: C_GOLD});
  api.endGroup();

  api.group('head', 'head');
    api.box({w: 2.5, h: 1.5, d: 2.0, pos: [0, 7.0, 0], color: C_LEAF});
    api.box({w: 1.5, h: 1.0, d: 1.5, pos: [0, 7.2, 1.2], color: C_LEAF});
    api.torus({r: 1.3, tube: 0.1, pos: [0, 6.5, 0], color: C_GOLD});
    api.sphere({r: 0.3, pos: [0.8, 7.3, 1.2], color: C_WHITE});
    api.poly({r: 0.15, pos: [0.9, 7.3, 1.4], color: C_BLACK});
    api.torus({r: 0.35, tube: 0.06, pos: [0.8, 7.3, 1.15], along: '+Z', color: C_GOLD});
    api.sphere({r: 0.3, pos: [-0.8, 7.3, 1.2], color: C_WHITE});
    api.poly({r: 0.15, pos: [-0.9, 7.3, 1.4], color: C_BLACK});
    api.torus({r: 0.35, tube: 0.06, pos: [-0.8, 7.3, 1.15], along: '+Z', color: C_GOLD});
  api.endGroup();

  api.group('dorsalFin', 'dorsalFin');
    api.patch({points: [[0, 5.5, -1.25], [0, 7.0, -2.5], [0, 8.5, -1.5], [0, 8.5, -0.8]], d: 0.3, color: C_LEAF_L});
    api.poly({r: 0.15, pos: [0, 8.5, -1.5], color: C_GOLD});
  api.endGroup();

  api.group('pectoralFin', 'pectoralFin');
    api.tri({a: [1.75, 5.0, 0], b: [3.0, 4.0, 0], c: [1.75, 4.0, 0], d: 0.3, color: C_LEAF_L});
    api.poly({r: 0.15, pos: [3.0, 4.0, 0], color: C_GOLD});
    api.tri({a: [-1.75, 5.0, 0], b: [-3.0, 4.0, 0], c: [-1.75, 4.0, 0], d: 0.3, color: C_LEAF_L});
    api.poly({r: 0.15, pos: [-3.0, 4.0, 0], color: C_GOLD});
  api.endGroup();
}
